from __future__ import print_function

import logging
import os
import re
import xml.etree.ElementTree as ET

import yaml

from taf.ul.bts_kpi_report_generator.converter.KPIErrorsHandler import KPIErrorsHandler

__author__ = 'Radoslaw Serafin, Michal Pabjan'
__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'radoslaw.serafin@nokia.com, michal.pabjan@nokia.com'


class ReleaseFileCreator:
    """
    Class for creating yaml release file by parsing xml NIDD database file .
    """

    def __init__(self, source_file_path):
        self.__source_file_path = source_file_path
        tree = ET.parse(self.__source_file_path)
        self.__root = tree.getroot()
        self.__release = self.__get_release_id()
        self.__kpi_error_handler = KPIErrorsHandler(source_file_path, self.__release)
        self.__parsed = {}
        self.__nested = {}
        self.__nested_array = []
        self.__KPI_ID = str()
        self.__XLSX_FORMULA = str()

    def __get_release_id(self):
        """
        Get's information about release ID from xml file

        :return: release ID
        """
        for ExportParameter in self.__root.iter('ExportParameter'):
            if ExportParameter.find('Parameter_Name').text == 'System Release':
                return ExportParameter.find('Parameter_Value').text

    def __fill_kpi_data(self, kpi):
        """
        Parses data about KPI from xml file into python dictionary

        :param kpi: KPI's ID to be parsed
        :return: None
        """
        try:
            self.__nested_array.append(kpi.find('KPI_Class').text)
            self.__nested_array = self.__kpi_error_handler.fix_uncommon_categories_bugs(self.__nested_array)
            self.__nested.update({'CATEGORY': self.__nested_array})
            self.__nested.update({"DESCRIPTION": str(kpi.find('Description').text).replace("\n", "")})
            for formula in kpi.iter('Formula_with_ID'):
                self.__nested.update({"FORMULA": str(formula.text).replace("\n", "")})
            if "FORMULA" not in self.__nested:
                self.__kpi_error_handler.unintended_phrase_error_handler.found_errors.append("No formula")
                self.__nested.update({"FORMULA": ""})
            self.__nested.update({"NAME": kpi.find('Name').text})
            self.__nested.update({"ABBREVIATION": kpi.find('Abbreviation').text})
            self.__nested.update({"LOGICAL_FORMULA": str(kpi.find('Logical_Formula').text).replace("\n", "")})
            self.__nested_array = []
            counters = dict()
            for dependency in kpi.iter('Dependendent_PI'):
                counters.update({dependency.find('PI_ID').text: dependency.find('PI_NAME').text})
            self.__nested.update({"DEPENDENCIES": counters})
            self.__nested.update({"UNIT": kpi.find('Unit').text})
        except Exception as other_errors:
            print(other_errors, "when trying to parse a KPI from xml into the dictionary:")

    def __adjust_formula_to_excel_form(self):
        """
        Changes some parts of formula KPI's into EXCELL format, e.g
        capitalize some phrases like 'sum' into 'SUM'
        changes 'avg' into 'AVERAGE'

        :return: None
        """
        for to_capitalize in self.__kpi_error_handler.double_asterix_error_handler.formula_fragments_to_capitalize:
            pattern = re.compile(to_capitalize, re.IGNORECASE)
            self.__XLSX_FORMULA = pattern.sub(to_capitalize.upper(), self.__XLSX_FORMULA)
        self.__XLSX_FORMULA = self.__XLSX_FORMULA.replace("AVG", "AVERAGE")
        self.__nested.update({"XLSX_FORMULA": self.__XLSX_FORMULA})

    def __save_data_to_files(self, path_to_xml_file, release):
        """
        Saves all collected data about KPI's into yaml files,

        :return: None
        """
        if not os.path.exists(path_to_xml_file):
            self.__kpi_error_handler.unintended_phrase_error_handler.ErrorsPrinter.info_print("File saved into current directory")
            self.__kpi_error_handler.unintended_phrase_error_handler.logger.info("File saved into current directory")

        new_parsed = {}
        for kpi in sorted(self.__parsed):
            new_parsed[kpi] = self.__parsed[kpi]
        self.__parsed = new_parsed
        savable_source_file_path = path_to_xml_file + "/"
        with open("{}release{}.yaml ".format(savable_source_file_path, release), 'w') as target_file:
            yaml.dump(self.__parsed, target_file, default_flow_style=False)
        with open("{}release_{}_KPIs_with_ERRORS.yaml".format(savable_source_file_path, release),
                  'w') as errors_target_file:
            concatenated_kpis_with_errors = self.__kpi_error_handler.concatenate_kpis_with_errors()
            yaml.dump(concatenated_kpis_with_errors, errors_target_file, default_flow_style=False)

    def __analyze_kpi_formula(self):
        """
        Analyze KPIs formula in search of errors

        :return: None
        """
        brackets_opened = bool()
        ar_range_end = 0
        for i, char in enumerate(self.__nested["FORMULA"]):
            self.__XLSX_FORMULA = self.__kpi_error_handler.double_asterix_error_handler.handle_double_asterisk_error(
                i,
                self.__nested,
                self.__KPI_ID,
                self.__XLSX_FORMULA)

            # Checking for any digit between arithmetic operators (checking for uninteded phrase)
            if self.__kpi_error_handler.unintended_phrase_error_handler.is_arithmetic(char) or i == len(self.__nested["FORMULA"]) - 1:
                ar_range_beg = ar_range_end
                ar_range_end = i
                self.__kpi_error_handler.unintended_phrase_error_handler.handle_unintended_phrase_error(ar_range_beg,
                                                                                                        ar_range_end,
                                                                                                        self.__nested,
                                                                                                        self.__KPI_ID)
            # Handling wrong brackets enclosure error
            if char == '[':
                brackets_opened = True
            if char == ']':
                if not brackets_opened:
                    self.__XLSX_FORMULA = self.__kpi_error_handler.wrong_brackets_enclosure_error_handler.handle_wrong_brackets_enclosure_error(
                        char,
                        i,
                        self.__nested,
                        self.__KPI_ID,
                        self.__XLSX_FORMULA)
                    continue
                brackets_opened = False

    def __update_main_dictionary(self):
        """
        Update main informations storage about KPI's

        :return: None
        """
        self.__kpi_error_handler.check_for_duplicates(self.__KPI_ID, self.__parsed)
        self.__kpi_error_handler.update_errors_storage(self.__KPI_ID)
        self.__nested = self.__kpi_error_handler.update_kpi_errors_info(self.__nested)
        self.__parsed.update({self.__KPI_ID: self.__nested})

    def create_release_file(self):
        """
        Main function, creates release file by parsing NIDD xml file,
        everything happens mainly in "Main for loop"

        :return: None
        """

        path_to_xml_file = os.path.dirname(self.__source_file_path)

        self.__kpi_error_handler.double_asterix_error_handler.logger = logging.getLogger()

        # Main for loop
        for KPI in self.__root.iter('KPI'):
            self.__fill_kpi_data(KPI)
            self.__KPI_ID = str(KPI.find("KPI_ID").text)
            self.__XLSX_FORMULA = self.__nested["FORMULA"]

            self.__kpi_error_handler.unintended_phrase_error_handler.potential_unintended_phrases = []
            self.__kpi_error_handler.wrong_brackets_enclosure_error_handler.adjustment = 0
            self.__analyze_kpi_formula()
            self.__kpi_error_handler.unintended_phrase_error_handler.check_for_unintended_phrases(self.__XLSX_FORMULA, self.__KPI_ID)
            self.__kpi_error_handler.unintended_phrase_error_handler.potential_unintended_phrases = []
            self.__XLSX_FORMULA = self.__XLSX_FORMULA.replace(" ", "")
            self.__kpi_error_handler.unintended_phrase_error_handler.find_unusual_counters(self.__KPI_ID, self.__XLSX_FORMULA)
            self.__kpi_error_handler.unintended_phrase_error_handler.check_for_unusual_counters(self.__KPI_ID, self.__XLSX_FORMULA)

            dependencies = set(self.__nested["DEPENDENCIES"].keys())

            if not self.__kpi_error_handler.unintended_phrase_error_handler.counters_from_formula.issubset(dependencies):
                self.__kpi_error_handler.unintended_phrase_error_handler.found_errors.append(
                    "No dependencies found : {}    (Formula has counters which are not "
                    "dependent due to lack of occurrence in its KPI "
                    "dependencies)".format(", ".join(
                        self.__kpi_error_handler.unintended_phrase_error_handler.counters_from_formula.difference(dependencies))))
                self.__kpi_error_handler.unintended_phrase_error_handler.ErrorsPrinter.error_print(
                    "No dependencies found",
                    "{} : {}".format(
                        self.__KPI_ID,
                        self.__kpi_error_handler.unintended_phrase_error_handler.counters_from_formula.difference(dependencies)))
                self.__kpi_error_handler.unintended_phrase_error_handler.logger.error("Dependencies incosistency {} : {}".format(
                    self.__KPI_ID, self.__kpi_error_handler.unintended_phrase_error_handler.counters_from_formula.difference(dependencies)))
                self.__kpi_error_handler.update_errors_storage(self.__KPI_ID)
                self.__adjust_formula_to_excel_form()
                self.__nested = self.__kpi_error_handler.update_kpi_errors_info(self.__nested)

                if not self.__kpi_error_handler.check_for_critical_errors():
                    self.__nested = self.__kpi_error_handler.update_lacking_dependencies(
                        dependencies,
                        self.__kpi_error_handler.unintended_phrase_error_handler.counters_from_formula,
                        self.__KPI_ID, self.__nested)
                    self.__update_main_dictionary()
                else:
                    '''
                    ATTENTION ! When "suspicious counter error" has been found in a KPI's formula
                    such KPI is filtered and not added into release file data
                    '''
                    self.__kpi_error_handler.filter_kpi(self.__KPI_ID, self.__parsed)
                self.__kpi_error_handler.clear_errors()
                self.__nested = {}
                self.__nested_array = []
                continue
            self.__adjust_formula_to_excel_form()
            self.__update_main_dictionary()
            self.__nested = {}
            self.__nested_array = []
            self.__kpi_error_handler.clear_errors()
        self.__save_data_to_files(path_to_xml_file, self.__release)
        self.__kpi_error_handler.check_errors_and_warn()
